        if not isinstance(node,(ast.Import,ast.ImportFrom)):continue
        if isinstance(node,ast.ImportFrom) and node.module=='__future__':continue
        scope=parents[node]
        while not isinstance(scope,(ast.Module,ast.FunctionDef,ast.AsyncFunctionDef,ast.ClassDef,ast.Lambda)):
            scope=parents[scope]
        aliases=defaultdict(list)
        for alias in node.names:
            if alias.name=='*':continue
            name=alias.asname or (alias.name if isinstance(node,ast.ImportFrom) else alias.name.split('.')[0])
