                constants[(item.lineno,item.end_lineno)].append({'name':item.value,'span':[item.lineno,item.col_offset,item.end_lineno,item.end_col_offset]})
        for span,items in constants.items():
            if len(items)>1:
                groups.append({'kind':'all_entry','path':path,'context':entry['context'],'lines':span,'source':ast.get_source_segment(source,node),'items':items,'explicit_pair':True})
